const input = $input.first().json;
const channel = input.channel || '#general';
const text = input.text || '';
const severity = input.severity || 'low';
const dedupeKey = input.dedupeKey || null;
const metadata = input.metadata || {};

if (!text) return [];

return [{ json: { channel, text, severity, dedupeKey, metadata, timestamp: new Date().toISOString() } }];

const input = $input.first().json;
if (!input.dedupeKey) return [{ json: input }];

const postgres = Postgres.main;
try {
  const recent = await postgres.query(`SELECT id FROM workflow_notifications WHERE dedupe_key = $1 AND created_at > NOW() - INTERVAL '15 minutes' LIMIT 1`, [input.dedupeKey]);
  if (recent.rows.length > 0) {
    return [];
  }
} catch (e) {}

return [{ json: input }];

const input = $input.first().json;
const postgres = Postgres.main;
try {
  await postgres.query(`INSERT INTO workflow_notifications (channel, severity, dedupe_key, message_preview, created_at) VALUES ($1, $2, $3, $4, CURRENT_TIMESTAMP)`, [input.channel, input.severity, input.dedupeKey, input.text.substring(0, 200)]);
} catch (e) {}
return [{ json: input }];
